args.command:
mkdir -p demo && cd demo && cat > buggy.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char *buf = (char *)malloc(8);
    if (!buf) {
        return 1;
    }
    strcpy(buf, "AAAAAAAAAAAAAAAA");
    printf("%s\n", buf);
    free(buf);
    return 0;
}
EOF

cc --version >/dev/null 2>&1 || true
clang --version >/dev/null 2>&1 && clang -fsanitize=address -g -o buggy_asan buggy.c || gcc -fsanitize=address -g -o buggy_asan buggy.c
ASAN_OPTIONS=verbosity=1:abort_on_error=1:detect_leaks=0 ./buggy_asan
